namespace A33.Instrument.Protocol;
public static class ModbusTcpCodec { public static byte[] Encode(ushort tid,byte unit,ReadOnlySpan<byte> pdu){if(pdu.Length>253)throw new ArgumentOutOfRangeException(nameof(pdu));var b=new byte[7+pdu.Length];b[0]=(byte)(tid>>8);b[1]=(byte)tid;b[4]=(byte)((pdu.Length+1)>>8);b[5]=(byte)(pdu.Length+1);b[6]=unit;pdu.CopyTo(b.AsSpan(7));return b;} public static (ushort Tid,byte Unit,ReadOnlyMemory<byte> Pdu) Decode(ReadOnlySpan<byte> adu,ushort expectedTid){if(adu.Length<8)throw new FormatException("short MBAP");var tid=(ushort)(adu[0]<<8|adu[1]);if(tid!=expectedTid)throw new FormatException("transaction mismatch");if(adu[2]!=0||adu[3]!=0)throw new FormatException("protocol id");var len=(ushort)(adu[4]<<8|adu[5]);if(len<2||len+6!=adu.Length)throw new FormatException("length");return(tid,adu[6],adu[7..].ToArray());} }
